    assert.doesNotMatch(hostHelp, /给出牌者 2 张手牌|支付 3 金币/);
    const peer = await state(guest);
    const hostRaw = JSON.stringify(await state(host));
    for (const card of peer.hand) assert(!hostRaw.includes(card.id), 'private card leaked');
    await host.keyboard.press('Escape');

    // Restart only this test's EXE while a real private reply is pending.
