    await guest.locator('[data-visitor-option="cards"]').waitFor();
    assert.equal((await state(guest)).pendingChoice.id, peer.pendingChoice.id);
    await guest.locator('[data-visitor-option="cards"]').click();
    await guide(guest);
    const eligible = guest.locator('#hand .visitor-eligible');
